cd "D:/Emma/MyLab/Mono2SLs/Mono2Sls-artifacts/M2S/runs/bookstore-m4" && python -c "
import json,glob
cited=set()
for f in glob.glob('judge/cases/*/*.json'):
    d=json.load(open(f,encoding='utf-8'))
    for r in d.get('fact_refs',[]): cited.add(r)
rep=json.load(open('storage/analysis_report.json',encoding='utf-8'))
miss=[]
for ep in rep['entry_points']:
    ref='%s %s'%(ep['method'],ep['path'])
    for i,b in enumerate(ep.get('business_rules',[])):
        r='%s#business_rules[%d]'%(ref,i)
        if r not in cited: miss.append((r,b.get('kind'),(b.get('rule') or '')[:60]))
print('uncited:',len(miss))
for r,k,t in miss: print(' -',r,'|',k,'|',t)
print()
print('new files ok:')
for f in sorted(glob.glob('judge/cases/*/wb-*.json'))+sorted(glob.glob('judge/faults/wb-*.json'))+['judge/spec_issues.json','judge/fixtures/books-bad-types.json']:
    d=json.load(open(f,encoding='utf-8')); print('  OK',f, (d.get('id') or len(d)))
"
